CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(24) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, nickname VARCHAR(60) NOT NULL, bio VARCHAR(300) NOT NULL DEFAULT '', role ENUM('USER','ADMIN') NOT NULL DEFAULT 'USER', status ENUM('ACTIVE','DISABLED') NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS categories (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(50) NOT NULL UNIQUE, is_enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS tags (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(50) NOT NULL UNIQUE, is_enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS articles (id BIGINT PRIMARY KEY AUTO_INCREMENT, author_id BIGINT NOT NULL, category_id BIGINT, title VARCHAR(80) NOT NULL, summary VARCHAR(200) NOT NULL, body_markdown TEXT NOT NULL, cover_path VARCHAR(500), status ENUM('DRAFT','PENDING','PUBLISHED','REJECTED','OFFLINE') NOT NULL DEFAULT 'DRAFT', is_featured BOOLEAN NOT NULL DEFAULT FALSE, first_published_at DATETIME, published_at DATETIME, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at DATETIME, FOREIGN KEY(author_id) REFERENCES users(id), FOREIGN KEY(category_id) REFERENCES categories(id), INDEX(status,published_at,id));
CREATE TABLE IF NOT EXISTS article_tags (article_id BIGINT NOT NULL, tag_id BIGINT NOT NULL, PRIMARY KEY(article_id,tag_id), FOREIGN KEY(article_id) REFERENCES articles(id), FOREIGN KEY(tag_id) REFERENCES tags(id));
CREATE TABLE IF NOT EXISTS series (id BIGINT PRIMARY KEY AUTO_INCREMENT, author_id BIGINT NOT NULL, name VARCHAR(40) NOT NULL, description VARCHAR(300) NOT NULL DEFAULT '', is_public BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS series_articles (series_id BIGINT NOT NULL, article_id BIGINT NOT NULL UNIQUE, sort_order INT NOT NULL, stage VARCHAR(20), PRIMARY KEY(series_id,article_id), FOREIGN KEY(series_id) REFERENCES series(id), FOREIGN KEY(article_id) REFERENCES articles(id));
CREATE TABLE IF NOT EXISTS comments (id BIGINT PRIMARY KEY AUTO_INCREMENT, article_id BIGINT NOT NULL, user_id BIGINT NOT NULL, parent_id BIGINT, content VARCHAR(500) NOT NULL, status ENUM('VISIBLE','DELETED','HIDDEN') NOT NULL DEFAULT 'VISIBLE', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(article_id) REFERENCES articles(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(parent_id) REFERENCES comments(id), INDEX(article_id,parent_id,created_at));
CREATE TABLE IF NOT EXISTS favorites (user_id BIGINT NOT NULL, article_id BIGINT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,article_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(article_id) REFERENCES articles(id));
CREATE TABLE IF NOT EXISTS notifications (id BIGINT PRIMARY KEY AUTO_INCREMENT, recipient_id BIGINT NOT NULL, actor_id BIGINT NOT NULL, type VARCHAR(32) NOT NULL, article_id BIGINT NOT NULL, comment_id BIGINT NOT NULL, summary VARCHAR(200) NOT NULL, event_key VARCHAR(100) NOT NULL UNIQUE, read_at DATETIME, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(recipient_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS sessions (sid VARCHAR(128) PRIMARY KEY, data TEXT NOT NULL, expires_at DATETIME NOT NULL, INDEX(expires_at));
